function persistDigestCandidate(){const raw=JSON.stringify(digestCandidate);try{localStorage.setItem(DIGEST_CANDIDATE_KEY,raw);try{sessionStorage.removeItem(DIGEST_CANDIDATE_KEY)}catch(_e){}return true}catch(e){console.warn("[IIG] localStorage candidate persistence failed; using sessionStorage fallback",e);try{sessionStorage.setItem(DIGEST_CANDIDATE_KEY,raw);adminToast("Digest candidate збережено у поточній сесії браузера.");return true}catch(e2){console.error("[IIG] Digest candidate persistence failed",e2);gate("Не вдалося зберегти Digest release-candidate навіть у сесії браузера. Очистіть локальні дані сайту або перезавантажте сторінку.");return false}}}
function restoreDigestCandidate(){try{const raw=localStorage.getItem(DIGEST_CANDIDATE_KEY)||sessionStorage.getItem(DIGEST_CANDIDATE_KEY)||"null";digestCandidate=JSON.parse(raw)}catch(e){digestCandidate=null}renderDigestCandidateState()}
function renderDigestCandidateState(){const el=$("digestCandidateState"),downloadBtn=$("downloadDigestHtml"),printBtn=$("printDigestPdf");if(!el)return;if(!digestCandidate){el.className="pill amber";el.textContent="CANDIDATE НЕ СФОРМОВАНО";if(downloadBtn)downloadBtn.disabled=true;if(printBtn)printBtn.disabled=true;return}const approved=digestCandidate.status==="ADMIN_1_APPROVED_DEMO_QA",previewed=digestCandidate.preview_completed===true;el.className="pill "+(approved?"green":previewed?"blue":"amber");el.textContent=(approved?"ADMIN_1 APPROVED · READY TO EXPORT · ":previewed?"PREVIEW COMPLETED · ":"AWAITING FINAL PREVIEW · ")+digestCandidate.issue+" · "+digestCandidate.generated_by;if(downloadBtn)downloadBtn.disabled=!approved;if(printBtn)printBtn.disabled=!approved}
function currentDigestIssueKey(){return String(digestIssue.year)+"-"+String(digestIssue.month).padStart(2,"0")}
function fingerprintSafe(v){if(v==null||typeof v==="number"||typeof v==="boolean")return v;if(typeof v==="string"){if(/^data:/i.test(v))return "__BINARY_DATA__:"+v.length+":"+v.slice(0,48)+":"+v.slice(-48);if(/^blob:/i.test(v))return "__BLOB_URL__";return v}if(Array.isArray(v))return v.map(fingerprintSafe);if(typeof v==="object"){const out={};Object.keys(v).sort().forEach(k=>{out[k]=fingerprintSafe(v[k])});return out}return String(v)}
function digestFingerprint(){const payload={issue:currentDigestIssueKey(),pages:digestPages.map(p=>({kind:p.kind,name:p.name,capacity:p.capacity,items:(p.items||[]).map(x=>({slug:x.slug,title:x.title,url:x.url,rubric:x.rubric})),design:fingerprintSafe(p.design||null),title:p.title||null,lead:p.lead||null,body:p.body||null,cta:p.cta||null,bg:fingerprintSafe(p.bg||null)})),cover:fingerprintSafe(coverDraft)};return JSON.stringify(payload)}
