let approvalLedger=new Map();
function approvalSnapshot(n){const x=JSON.parse(JSON.stringify(n));delete x.demo_approval;if(x.image_choice&&x.image_choice.preview_data)delete x.image_choice.preview_data;x.approval_locked=true;x.approval_locked_by=ACTIVE_ADMIN.id;x.approval_locked_at=new Date().toISOString();return x}
function persistApprovalLedger(){try{localStorage.setItem(APPROVAL_LEDGER_KEY,JSON.stringify([...approvalLedger.entries()]));syncApprovalLedgerUI();return true}catch(e){console.error("[IIG] approval ledger persistence failed",e);gate("Не вдалося зберегти Approval Ledger у браузері.");return false}}
