function freezeApprovedSet(){if(!requireAdmin1("ЗАФІКСУВАТИ ВЕСЬ ЗАТВЕРДЖЕНИЙ МАТЕРІАЛ"))return;let locked=0,review=0;for(const base of items){const n=drafts.get(base.slug)||approvalLedger.get(base.slug)||base;if(["APPROVED","PUBLISHED"].includes(n.status)&&n.admin_approved===true&&(n.content_type!=="NEWS"||n.image_admin_approved===true)){approvalLedger.set(n.slug,approvalSnapshot(n));locked++}else if(["DRAFT","REVIEW"].includes(n.status))review++}if(!persistApprovalLedger())return;auditEvent("Зафіксовано весь затверджений матеріал","Approval Ledger",locked+" items");adminToast("Зафіксовано "+locked+" затверджених матеріалів. REVIEW не змінено: "+review+".")}

