function persistPublishedBridge(n){try{const raw=JSON.parse(localStorage.getItem(PUBLIC_DEMO_PUBLISHED_KEY)||"[]"),arr=Array.isArray(raw)?raw:[],map=new Map(arr.map(x=>[x.slug,x]));map.set(n.slug,publicBridgeItem(n));localStorage.setItem(PUBLIC_DEMO_PUBLISHED_KEY,JSON.stringify([...map.values()]));return true}catch(e){console.error("[IIG] published bridge persistence failed",e);return false}}
