function exportEditorialSession(){const payload={schema:"iig.admin-editorial-session.v1",exported_at:new Date().toISOString(),items:[...drafts.values()].map(x=>({...x,demo_approval:undefined}))};const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([JSON.stringify(payload,null,2)],{type:"application/json"}));a.download="IIG_Admin_Editorial_Session_"+new Date().toISOString().slice(0,10)+".json";a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);auditEvent("Експорт редакційної сесії","JSON",payload.items.length+" матеріалів")}
