function packBalancedFinancePage(finance,regulation){const p=digestPages.find(x=>x.kind==="finance");if(!p)return {used:new Set(),finance:0,regulation:0};p.items=[];const used=new Set();let fi=0,ri=0;const take=(arr,kind)=>{for(const item of arr){if(!pageFits(p,item))break;p.items.push(item);used.add(item.slug);if(kind==="FINANCE")fi++;else ri++;return true}return false};while(pageFree(p)>=1&&(finance.length||regulation.length)){let progressed=false;if(fi<=ri&&finance.length){const x=finance.shift();if(pageFits(p,x)){p.items.push(x);used.add(x.slug);fi++;progressed=true}else finance.unshift(x)}if(pageFree(p)>=1&&ri<=fi&&regulation.length){const x=regulation.shift();if(pageFits(p,x)){p.items.push(x);used.add(x.slug);ri++;progressed=true}else regulation.unshift(x)}if(!progressed){const arr=finance.length?finance:regulation;if(!arr.length)break;const x=arr.shift();if(pageFits(p,x)){p.items.push(x);used.add(x.slug);if(x.rubric==="FINANCE")fi++;else ri++;progressed=true}else break}}return {used,finance:fi,regulation:ri}}
function autoFillDigest(showMessage=true){const extras=digestPages.filter(p=>p.kind==="promo"||p.kind==="article");digestPages=digestPages.filter((p,i)=>i<3);digestPages.forEach(p=>p.items=[]);const pool=approved().filter(n=>digestRubric(n)!=="ADVICE"&&issueMatches(n)).map(makeDigestItem),general=pool.filter(x=>x.rubric==="GENERAL"),finance=pool.filter(x=>x.rubric==="FINANCE"),regulation=pool.filter(x=>x.rubric==="REGULATION");general.forEach(placePacked);const fcopy=[...finance],rcopy=[...regulation],balanced=packBalancedFinancePage(fcopy,rcopy),remaining=[...finance,...regulation].filter(x=>!balanced.used.has(x.slug));remaining.forEach(item=>{const candidates=digestPages.filter(p=>p.kind==="news");let p=candidates.find(x=>pageFits(x,item));if(!p){p=ensureNewsPage();while(!pageFits(p,item)){p={name:"Сторінка "+(digestPages.length+1)+" — Новини",kind:"news",capacity:PAGE_CAPACITY.news,items:[]};digestPages.push(p)}}p.items.push(item)});digestPages.push(...extras);auditEvent("Автозаповнення дайджесту",pool.length+" матеріалів","PAGE3 BALANCED "+balanced.finance+"/"+balanced.regulation+" · OVERFLOW PAGE4+");renderDigest();if(showMessage)gate("Автозаповнення завершено: Page 3 резервує місце для Порад + CTA і заповнюється максимально щільно збалансованими Finance / Regulation. Решта матеріалів автоматично переходить на Page 4+.")}
function digestCandidateChecks(){const all=digestPages.flatMap(p=>p.items),advice=fixedAdvice(),overflow=digestPages.filter(p=>["news","finance"].includes(p.kind)&&pageUsed(p)>p.capacity+.001),bad=all.filter(x=>!x.url||!x.slug);return [
["Матеріали у candidate",all.length,all.length>0],
["Поради у фіксованому блоці",advice.length,advice.length===3],
["Page 3 Finance / Regulation баланс",(()=>{const p=digestPages.find(x=>x.kind==="finance"),f=(p?.items||[]).filter(x=>x.rubric==="FINANCE").length,r=(p?.items||[]).filter(x=>x.rubric==="REGULATION").length;return f+"/"+r})(),(()=>{const p=digestPages.find(x=>x.kind==="finance"),f=(p?.items||[]).filter(x=>x.rubric==="FINANCE").length,r=(p?.items||[]).filter(x=>x.rubric==="REGULATION").length;return Math.abs(f-r)<=1})()],
["Переповнені сторінки",overflow.length,overflow.length===0],
["Некоректні direct links",bad.length,bad.length===0],
["Фон обкладинки підтверджено ADMIN_1",coverDraft.isDefault?"MASTER":(coverDraft.bgApprovedBy||"НІ"),coverDraft.isDefault||coverDraft.bgApproved===true],
["Сторінки Digest",digestPages.length,digestPages.length>=3]
]}
function buildDigestReleaseCandidate(){if(!requireDigestBuilder("СФОРМУВАТИ НОВИЙ ДАЙДЖЕСТ"))return;autoFillDigest(false);const checks=digestCandidateChecks(),ok=checks.every(x=>x[2]);if(!ok){renderFinalChecks();return gate("DIGEST_CANDIDATE_BLOCKED: усуньте структурні помилки candidate — переповнення, direct links, обкладинку або відсутній затверджений контент.")}const all=digestPages.flatMap(p=>p.items);digestCandidate={schema:"iig.digest-release-candidate.v2",issue:currentDigestIssueKey(),status:"AWAITING_ADMIN_1_PREVIEW",generated_by:digestWorkflowRole,generated_at:new Date().toISOString(),master:"APPROVED_MASTER_V2_LATEST_RULESET",page_count:digestPages.length,item_count:all.length,advice_count:fixedAdvice().length,source:"CURRENT_APPROVAL_LEDGER_AND_CMS",auto_send:false,final_approval:false,preview_completed:false,previewed_at:null,previewed_by:null,preview_fingerprint:null,fingerprint:digestFingerprint()};if(!persistDigestCandidate())return;renderDigestCandidateState();auditEvent("Сформовано Digest release-candidate",digestCandidate.issue,digestWorkflowRole+" · "+all.length+" items");adminToast("Digest candidate сформовано. Наступний обов’язковий крок — «ФІНАЛЬНИЙ ПЕРЕГЛЯД ВЕРСТКИ», після нього ADMIN_1 може затверджувати макет.")}
function digestFinalChecks(){const all=digestPages.flatMap(p=>p.items),advice=fixedAdvice(),overflow=digestPages.filter(p=>["news","finance"].includes(p.kind)&&pageUsed(p)>p.capacity+.001),bad=all.filter(x=>!x.url||!x.slug),bySlug=new Map(items.map(n=>[n.slug,effective(n)])),includedUnapproved=all.filter(x=>{const n=bySlug.get(x.slug);return !n||!(["APPROVED","PUBLISHED"].includes(n.status)&&n.admin_approved===true&&(n.content_type!=="NEWS"||n.image_admin_approved===true))});return [
["Матеріали candidate підтверджені ADMIN_1",all.length-includedUnapproved.length,includedUnapproved.length===0&&all.length>0],
["Непідтверджені матеріали всередині candidate",includedUnapproved.length,includedUnapproved.length===0],
["Поради у фіксованому блоці",advice.length,advice.length===3],
["Переповнені сторінки",overflow.length,overflow.length===0],
["Некоректні direct links",bad.length,bad.length===0],
["Фон обкладинки підтверджено ADMIN_1",coverDraft.isDefault?"MASTER":(coverDraft.bgApprovedBy||"НІ"),coverDraft.isDefault||coverDraft.bgApproved===true],
["Сторінки Digest",digestPages.length,digestPages.length>=3]
]}
function renderFinalChecks(){if(!$("finalPreviewChecks"))return;const checks=digestFinalChecks();$("finalPreviewChecks").innerHTML=checks.map(x=>'<div class="readinessitem"><span>'+esc(x[0])+'</span><b>'+x[1]+'</b><span class="pill '+(x[2]?"green":"amber")+'">'+(x[2]?"OK":"BLOCK")+'</span></div>').join("");const ok=checks.every(x=>x[2]);$("finalPreviewState").className="pill "+(ok?"green":"amber");$("finalPreviewState").textContent=ok?"READY FOR ADMIN FINAL REVIEW":"ПОТРІБНА МОДЕРАЦІЯ";return ok}
function digestEndCtas(){return '<div class="digest-end-ctas"><a href="forms.html#project">РОЗМІСТИТИ ПРОЄКТ</a><a href="forms.html#subscribe">ПІДПИСАТИСЯ НА ДАЙДЖЕСТ</a></div>'}
function finalPageMarkup(p,i){const advice=fixedAdvice(),needsCtas=i>=2,endCtas=needsCtas?digestEndCtas():"";if(p.kind==="cover")return '<section class="finaldigestpage">'+coverMarkup(p.design||coverDraft)+'</section>';if(p.kind==="promo")return '<section class="finaldigestpage">'+extraPageMarkup(p)+endCtas+'</section>';if(p.kind==="article")return '<section class="finaldigestpage">'+articlePageMarkup({...p,pageNumber:i+1})+endCtas+'</section>';const itemsMarkup=p.items.map((x,k)=>'<div class="finaldigestitem"><span>'+String(k+1).padStart(2,"0")+'</span><a href="'+esc(x.url)+'">'+esc(x.title)+'</a></div>').join("");const adviceMarkup=p.kind==="finance"?'<div class="finaladvice"><b>ПОРАДИ ГОЛОВНОГО ІНЖЕНЕРА</b>'+advice.map(a=>'<a class="finaladvice-link" href="'+esc(publicUrl(a))+'"><span class="finaladvice-title">'+esc(titleOf(a))+'</span><span class="finaladvice-more">Детальніше →</span></a>').join("")+'</div>':"";return '<section class="finaldigestpage finalcorepage digest-page-'+(i+1)+'"><header><small>IIG Monthly Digest · '+esc(MONTHS_UA[digestIssue.month-1]+' '+digestIssue.year)+'</small><b>'+(p.kind==="finance"?"ФІНАНСИ · ЗАКОНОДАВСТВО · ПОРАДИ":"УКРАЇНА ТА СВІТ")+'</b></header><div class="finaldigestitems">'+itemsMarkup+'</div>'+adviceMarkup+endCtas+'</section>'}
function assertApprovedDigestArtifact(){if(!digestCandidate||digestCandidate.status!=="ADMIN_1_APPROVED_DEMO_QA"||digestCandidate.final_approval!==true){gate("Спочатку сформуйте candidate, відкрийте фінальний перегляд і затвердьте фінальний макет ADMIN_1.");return false}if(digestCandidate.fingerprint!==digestFingerprint()||digestCandidate.preview_fingerprint!==digestFingerprint()){gate("Макет змінився після Final Preview / approval. Сформуйте candidate і затвердьте його повторно.");return false}return true}
function absolutizeDigestMarkup(markup){const host=document.createElement("div");host.innerHTML=markup;host.querySelectorAll("a[href]").forEach(a=>{const href=a.getAttribute("href");if(!href||href.startsWith("data:")||href.startsWith("mailto:")||href.startsWith("#"))return;try{a.href=new URL(href,location.href).href}catch(e){}});host.querySelectorAll(".digestcover-bgmeta").forEach(x=>x.remove());return host.innerHTML}
