async function printApprovedDigestPdf(){const html=await buildStandaloneDigestHtml();if(!html)return;const w=window.open("","_blank","noopener");if(!w)return gate("Браузер заблокував вікно PDF. Дозвольте pop-up для цієї адмінки.");w.document.open();w.document.write(html);w.document.close();digestCandidate.pdf_save_opened_at=new Date().toISOString();persistDigestCandidate();auditEvent("Зберегти Digest як PDF через ADMIN",currentDigestIssueKey(),"EXACT APPROVED STATE · ACTIVE LINKS");setTimeout(()=>{try{w.focus();w.print()}catch(e){}},700)}
