function movePage(p,i){const item=digestPages[p].items[i];const t=Number(prompt("Перемістити на сторінку № (1-"+digestPages.length+")",String(Math.min(p+2,digestPages.length))))-1;if(!Number.isInteger(t)||t<0||t>=digestPages.length||t===p)return;if(!pageFits(digestPages[t],item))return gate("На вибраній сторінці недостатньо місця або рубрика несумісна з макетом. Система не допускає переповнення.");digestPages[t].items.push(digestPages[p].items.splice(i,1)[0]);renderDigest()}
