function renderReleaseReadiness(){if(!$("releaseReadiness"))return;const arr=[...new Map(items.map(n=>[n.slug,effective(n)])).values()].filter(issueMatches),ok=arr.filter(n=>["APPROVED","PUBLISHED"].includes(n.status)&&n.admin_approved),counts={general:ok.filter(n=>digestRubric(n)==="GENERAL").length,finance:ok.filter(n=>digestRubric(n)==="FINANCE").length,regulation:ok.filter(n=>digestRubric(n)==="REGULATION").length,advice:ok.filter(n=>digestRubric(n)==="ADVICE").length,draft:arr.filter(n=>["DRAFT","REVIEW"].includes(n.status)).length,badlink:ok.filter(n=>n.content_type!=="ADVICE"&&!n.slug).length};const checks=[["Україна / Світ",counts.general,counts.general>=1],["Фінанси",counts.finance,counts.finance>=1],["Законодавство / Регулювання",counts.regulation,counts.regulation>=1],["Поради Головного інженера",counts.advice,counts.advice>=3],["Чернетки / На перевірці",counts.draft,counts.draft===0],["Матеріали без direct ID",counts.badlink,counts.badlink===0]];$("releaseReadiness").innerHTML=checks.map(x=>'<div class="readinessitem"><span>'+esc(x[0])+'</span><b>'+x[1]+'</b><span class="pill '+(x[2]?"green":"amber")+'">'+(x[2]?"OK":"УВАГА")+'</span></div>').join("");const ready=checks.every(x=>x[2]);$("releaseReadinessState").className="pill "+(ready?"green":"amber");$("releaseReadinessState").textContent=ready?"READY FOR DIGEST":"ПОТРІБНА МОДЕРАЦІЯ"}
